package net.officefloor.hq.app.sheet;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    public record SheetView(String id, LocalDate today, boolean archived, Long lastBatch) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived(), sheet.getLastBatchNumber());
        }
    }

    public record TodayRequest(@NotNull LocalDate today) {
    }

    private final SheetService service;
    private final RollupService rollups;
    private final PeriodService periods;
    private final SettingService settings;
    private final ClaimService claims;

    public SheetController(SheetService service, RollupService rollups, PeriodService periods, SettingService settings,
            ClaimService claims) {
        this.service = service;
        this.claims = claims;
        this.rollups = rollups;
        this.periods = periods;
        this.settings = settings;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 200) String id) {
        return SheetView.of(service.load(id.trim()));
    }

        return then;
    }

    /** Keep a value set for a sheet setting that is not dated (null: blank), with the sheet's today. */
    public void settingSet(String sheetId, String key, String value) {
        jdbc.update("INSERT INTO sheet_setting_history (sheet_id, setting_key, setting_value, made_on)"
                + " SELECT id, ?, ?, today FROM sheet WHERE id = ?", key, value, sheetId);
    }

    /** The values of the sheet's settings that are not dated as they stood set at the end of a day, by
     *  key (a value null for blank); a key never set by then is absent. */
    public Map<String, String> settings(String sheetId, LocalDate day) {
        Map<String, String> then = new LinkedHashMap<>();
        jdbc.query("SELECT setting_key, setting_value FROM sheet_setting_history WHERE sheet_id = ? AND made_on <= ?"
                        + " ORDER BY id",
                (rs, n) -> new String[] {rs.getString("setting_key"), rs.getString("setting_value")},
                sheetId, day).forEach(pair -> then.put(pair[0], pair[1]));
        return then;
    }

    /** The keys of the sheet's settings that are not dated whose values were ever kept. */
    public List<String> settingsKept(String sheetId) {
        return jdbc.queryForList("SELECT DISTINCT setting_key FROM sheet_setting_history WHERE sheet_id = ?",
                String.class, sheetId);
    }

    /** A grade's rates on the sheet as they stood at the end of a day: for each from-date, the rate
     *  last set from it by then. */
    public List<Rate> rates(String sheetId, String grade, LocalDate day) {
        Map<LocalDate, Rate> byFrom = new LinkedHashMap<>();
        jdbc.query("SELECT * FROM rate_history WHERE sheet_id = ? AND grade = ? AND made_on <= ? ORDER BY id",
                (rs, n) -> new Rate(sheetId, grade, rs.getObject("from_date", LocalDate.class),
                        rs.getObject("to_date", LocalDate.class), rs.getBigDecimal("rate")),
                sheetId, grade, day).forEach(rate -> byFrom.put(rate.getFrom(), rate));
        return new ArrayList<>(byFrom.values());
    }


@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it; the rate is a percent string with two decimals, the
     *  from-date null when the rate applies from the beginning of time. */
    public record RateView(String grade, String rate, LocalDate from, LocalDate to) {
        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getRate().toPlainString(), rate.getFrom(), rate.getTo());
        }
    }

    /** A rate: a percent of 0.00 or more with up to two decimals, and the date it applies from
     *  (blank: from the beginning of time) and the last date it applies on (blank: no end). */
    public record RateRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal rate,
            LocalDate from, LocalDate to) {
    }

    /** A rate preview as the screen shows it: how many claims would show a different due, and the
     *  sum of the differences with two decimals. */
    public record RatePreviewView(int count, String diff) {
    }

    private final RateService service;
    private final RollupService rollups;
    private final ClaimService claims;

    public RateController(RateService service, RollupService rollups, ClaimService claims) {
        this.service = service;
        this.rollups = rollups;
        this.claims = claims;
    }

    /** The sheet's rates by grade, each grade's from the earliest; a grade with no rate is not listed.
     *  As they stand now, or as they stood at the end of the screen's as-of date. */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        return service.list(sheetId.trim(), AsOf.parse(asOf)).stream().map(RateView::of).toList();
    }

    /** Set the rate for a grade (A, B or C) from a date, replacing the one it had from that date. */
    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated RateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return RateView.of(rollups.track(sheet, by, () -> service.set(sheet, by, grade, request.from(),
                request.to(), request.rate())));
    }

    /** Preview a candidate rate for a grade (A, B or C): how the dues of the OPEN and PENDING claims of
     *  people on the grade would change were it the grade's rate on every date. Nothing is saved. */
    @GetMapping("/{grade}/preview")
    public RatePreviewView preview(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String rate) {
        ClaimService.RatePreview preview = claims.previewRate(sheetId.trim(), grade, new BigDecimal(rate).setScale(2));
        return new RatePreviewView(preview.count(), preview.diff().toPlainString());
    }

    /** A rate that is not a number or a from-date that is not a real date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }

    /** A to-date before the from-date is refused. */
    @ExceptionHandler(RateRefusedException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void refused() {
    }

    /** The grade's rate from that date was first set concurrently; caught by the unique index. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void conflict() {
    }
}

